import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

pub fn main() effect io -> Result<(), AppError> {
    let c = Cell { n: 5 }
    let m = conc.Mutex(0)
    var n: Int64 = 0
    n = m.update(|v| v + c.n)
    io.println("${n}")
    return Ok(())
}
